import Foundation
import simd

/// P02.0: the puzzle graph and its rules (`Game/PuzzleGraph.swift`, `docs/plans/P02-puzzle-restructure.md` section 2.3).
///  - Each rule is proved on SYNTHETIC graphs: a clean graph passes every rule, and a copy broken in exactly one way is flagged by exactly the rule that should flag it. Without this a rule that
///    always returns nothing would look like a game with no rule breaks.
///  - Today's graph (built from the live game) is not required to be clean (P02.0 fixes nothing). Its list of rule breaks is PINNED below: a new break fails, and so does a break that goes away
///    unnoticed. A real fix updates the pin and `docs/plans/P02-graph-report.md` (regenerate with `--puzzle-graph docs/plans/P02-graph-report.md`).
extension SelfTestRunner {
    /// Today's rule breaks (rule + subject), regenerated by `--puzzle-graph`. Update this on purpose when a break is fixed or a puzzle is added.
    static let pinnedPuzzleBreaks: [String] = [
        "G4 door-plates the stones' order", "G4 stones page 2", "G4 stones page 3",
        "G5 archive-gates+chime-pool+door-plates+mirror-court+stones",
        "G6 chime-pool", "G6 door-plates",
        "G7 door-plates senses", "G7 lens-ring senses", "G7 mirror-court senses",
        "G8 archive-gates-beam manipulations", "G8 door-plates clues", "G8 mirror-court manipulations",
        "G9 archive-gates+lens-ring", "G9 chime-pool+door-plates+stones",
        "G10 archive-gates-beam page 13", "G10 archive-gates-tone page 13", "G10 door-plates page 3", "G10 door-plates page 5", "G10 door-plates page 6", "G10 mirror-court page 5", "G10 stones page 3",
    ].sorted()

    // MARK: Synthetic graphs

    /// Two worlds. In the first, A and B are open together and each opens one more (C after A, D after B), so there are always two to choose from until the last; every clue is a page in the
    /// other world; every answer, verb and channel differs; every machine answers on two senses within half a second with progress.
    private static func cleanGraph() -> PuzzleGraph {
        func node(_ id: String, _ needs: [String], _ sets: String, verb: String, channel: PuzzleChannel, answer: [String], page: Int) -> PuzzleNode {
            PuzzleNode(id: id, title: id, world: .varrow, verb: verb, channel: channel, answer: answer, manipulations: 4, requires: needs, sets: sets, machine: [SIMD3(0, 0, 0)],
                       clues: [PuzzleClue(source: .page(page), world: .glassWood, position: SIMD3(500, 0, 0), label: "page \(page)")],
                       feedback: [PuzzleFeedback(sense: .sight, kind: .progress, seconds: 0.3, note: "a light that grows"), PuzzleFeedback(sense: .sound, kind: .progress, seconds: 0.2, note: "a tone that sweetens")])
        }
        let nodes = [node("A", ["go"], "a", verb: "strike", channel: .hear, answer: ["x", "y"], page: 1),
                     node("B", ["go"], "b", verb: "turn", channel: .aim, answer: ["y", "z"], page: 2),
                     node("C", ["a"], "c", verb: "count", channel: .count, answer: ["z", "x"], page: 3),
                     node("D", ["b"], "d", verb: "watch", channel: .watch, answer: ["x", "z"], page: 4)]
        return PuzzleGraph(puzzles: nodes, pages: (1...4).map { PageFact(id: $0, world: .glassWood, position: SIMD3(500, 0, 0), states: []) }, external: ["go"])
    }

    func runPuzzleGraph() {
        guard name == "all" || name == "puzzlegraph" else { return }

        // The rule's own text reader.
        typealias R = PuzzleRules
        check(R.statedAnswer("I tune the lamp each evening: from the water, through the wind, to the stone. Out of order, they only argue.") == ["tide", "wind", "stone"], "puzzlegraph: a sentence naming water, wind, stone in order states the answer")
        check(R.statedAnswer("Tide first. Then wind. Then stone.") == ["tide", "wind", "stone"], "puzzlegraph: 'Tide first. Then wind. Then stone.' states the answer")
        check(R.statedAnswer("Stone, wind, water.").isEmpty, "puzzlegraph: the same words in the wrong order state nothing")
        check(R.statedAnswer("The old standing stones remember the sea; the wind is cold and the tide is out.").isEmpty, "puzzlegraph: 'stones' (plural) and loose mentions state nothing")
        check(R.statedAnswer("water " + String(repeating: "and so on ", count: 30) + "wind then stone").isEmpty, "puzzlegraph: three words far apart state nothing")

        // A clean graph passes every rule; one broken copy per rule is flagged by exactly that rule (plus what must follow from it).
        let clean = Self.cleanGraph()
        check(R.breaks(clean).isEmpty, "puzzlegraph: the clean fixture passes every rule (\(R.breaks(clean).map(\.key)))")
        let steps = R.timeline(clean)
        check(steps.map(\.id) == ["A", "B", "C", "D"] && steps.map { $0.open.count } == [2, 2, 2, 1], "puzzlegraph: the clean fixture's timeline is 2, 2, 2 choices then the last one (\(steps.map { $0.open.count }))")

        func rules(_ g: PuzzleGraph) -> Set<String> { Set(R.breaks(g).map(\.rule)) }
        func broken(_ change: (inout PuzzleGraph) -> Void) -> PuzzleGraph { var g = clean; change(&g); return g }
        func idx(_ g: PuzzleGraph, _ id: String) -> Int { g.puzzles.firstIndex { $0.id == id }! }

        let cycle = broken { $0.puzzles[idx($0, "A")].requires = ["c"] }                                         // A waits for C, which waits for A
        check(rules(cycle) == ["G1"] && R.acyclic(cycle).contains { $0.subject == "cycle" }, "puzzlegraph G1: a cycle of puzzles is flagged (\(rules(cycle)))")
        let orphan = broken { $0.puzzles[idx($0, "B")].requires = ["nothing-sets-this"] }
        check(rules(orphan) == ["G1", "G2"], "puzzlegraph G1/G2: a flag nobody sets cuts the puzzle off and is named (\(rules(orphan)))")
        let loose = broken { $0.pages.append(PageFact(id: 9, world: .glassWood, position: SIMD3(0, 0, 0), states: ["x", "y"])) }
        check(rules(loose) == ["G3"], "puzzlegraph G3: a page that states an answer and is nobody's clue is flagged (\(rules(loose)))")
        let ghost = broken { $0.puzzles[idx($0, "A")].clues.append(PuzzleClue(source: .memory(of: "nope"), world: .varrow, position: nil, label: "a memory of a puzzle that is not there")) }
        check(R.clueConsumers(ghost).contains { $0.rule == "G3" && $0.subject.hasPrefix("A clue") }, "puzzlegraph G3: a clue that points at a puzzle that does not exist is flagged")
        let near = broken { $0.puzzles[idx($0, "A")].clues = [PuzzleClue(source: .page(1), world: .varrow, position: SIMD3(5, 0, 0), label: "page 1")] }
        check(rules(near) == ["G4"], "puzzlegraph G4: a clue 5 m from its machine is flagged (\(rules(near)))")
        let farOK = broken { $0.puzzles[idx($0, "A")].clues = [PuzzleClue(source: .page(1), world: .varrow, position: SIMD3(41, 0, 0), label: "page 1")] }
        check(R.breaks(farOK).isEmpty, "puzzlegraph G4: a clue 41 m away is fine (the limit is 40)")
        let nearMem = broken { $0.puzzles[idx($0, "C")].clues = [PuzzleClue(source: .memory(of: "A"), world: .varrow, position: nil, label: "A's result")] }
        check(rules(nearMem) == ["G4"], "puzzlegraph G4: a memory of a puzzle whose machine is at this machine is flagged (\(rules(nearMem)))")
        let sameAnswer = broken { $0.puzzles[idx($0, "C")].answer = $0.puzzles[idx($0, "A")].answer }
        check(rules(sameAnswer) == ["G5"], "puzzlegraph G5: two puzzles with one answer are flagged (\(rules(sameAnswer)))")
        let altOK = broken { $0.puzzles[idx($0, "C")].answer = $0.puzzles[idx($0, "A")].answer; $0.puzzles[idx($0, "C")].group = "g"; $0.puzzles[idx($0, "A")].group = "g"
                             $0.puzzles[idx($0, "C")].verb = "other"; $0.puzzles[idx($0, "C")].channel = .see }
        check(!rules(altOK).contains("G5") && !rules(altOK).contains("G9"), "puzzlegraph G5: two ways of one machine (a group) may share an answer")
        let chain = broken { $0.puzzles[idx($0, "B")].requires = ["a"]; $0.puzzles[idx($0, "C")].requires = ["b"]; $0.puzzles[idx($0, "D")].requires = ["c"] }          // A, then B, then C, then D: one at a time
        check(rules(chain) == ["G6"], "puzzlegraph G6: a chain (one open at each choice) is flagged (\(rules(chain)), steps \(R.timeline(chain).map { $0.open.count }))")
        let noFeedback = broken { $0.puzzles[idx($0, "B")].feedback = [] }
        check(rules(noFeedback) == ["G7"] && R.feedback(noFeedback).count == 2, "puzzlegraph G7: no feedback fails both progress and two senses (\(R.feedback(noFeedback).map(\.subject)))")
        let oneSense = broken { $0.puzzles[idx($0, "B")].feedback = [PuzzleFeedback(sense: .sight, kind: .progress, seconds: 0.3, note: ""), PuzzleFeedback(sense: .sound, kind: .binary, seconds: 0.1, note: "")] }
        check(R.feedback(oneSense).map(\.subject) == ["B senses"], "puzzlegraph G7: a second sense that only says 'done' does not count (\(R.feedback(oneSense).map(\.subject)))")
        let slow = broken { $0.puzzles[idx($0, "B")].feedback[1].seconds = 2.5 }
        check(R.feedback(slow).map(\.subject) == ["B senses"], "puzzlegraph G7: an answer that comes after 2.5 s does not count (\(R.feedback(slow).map(\.subject)))")
        let big = broken { $0.puzzles[idx($0, "A")].manipulations = 9 }
        check(rules(big) == ["G8"], "puzzlegraph G8: nine manipulations are over the budget (\(rules(big)))")
        let many = broken { $0.puzzles[idx($0, "A")].clues += [PuzzleClue(source: .page(2), world: .glassWood, position: nil, label: "p2"), PuzzleClue(source: .page(3), world: .glassWood, position: nil, label: "p3")] }
        check(rules(many) == ["G8"], "puzzlegraph G8: three clue sources are over the budget (\(rules(many)))")
        let twin = broken { $0.puzzles[idx($0, "B")].verb = "strike"; $0.puzzles[idx($0, "B")].channel = .hear }
        check(rules(twin) == ["G9"], "puzzlegraph G9: two puzzles with one verb and channel are flagged (\(rules(twin)))")
        let sentence = broken { g in
            g.pages[0].states = g.puzzles[idx(g, "A")].answer
        }
        check(rules(sentence) == ["G10"], "puzzlegraph G10: a clue page that says the puzzle's own answer in words is flagged (\(rules(sentence)))")
        let storyOK = broken { $0.puzzles[idx($0, "A")].kind = .story; $0.puzzles[idx($0, "A")].feedback = []; $0.puzzles[idx($0, "A")].manipulations = 0 }
        check(!rules(storyOK).contains("G7") && !rules(storyOK).contains("G8"), "puzzlegraph: a story beat is not scored as a puzzle")

        // Today's game.
        let scenes: [WorldKind: Scene] = [.varrow: Scene.make(.varrow, device: device), .glassWood: Scene.make(.glassWood, device: device), .tideArchive: Scene.make(.tideArchive, device: device)]
        let game = Game(scenes: scenes)
        let g = PuzzleGraph.today(game: game)
        let found = R.breaks(g).map(\.key).sorted()
        check(found == Self.pinnedPuzzleBreaks, "puzzlegraph: today's rule breaks are exactly the pinned list (\(found.count) found, \(Self.pinnedPuzzleBreaks.count) pinned; new: \(found.filter { !Self.pinnedPuzzleBreaks.contains($0) }); gone: \(Self.pinnedPuzzleBreaks.filter { !found.contains($0) }))")

        // The graph is the game's, not a copy: every machine is a real box, every flag is one the game sets, the answers are the puzzles' own constants.
        let missing = g.puzzles.flatMap { n in n.machineIDs.filter { id in !game.interactables(in: n.world).contains { $0.id == id } }.map { "\(n.id): \($0)" } }
        check(missing.isEmpty && g.puzzles.allSatisfy { $0.machine.count == $0.machineIDs.count }, "puzzlegraph: every machine of the graph is an interactable of its world (\(missing))")
        let gameFlags = Set(game.puzzle.persistentFlags + (game.glass?.persistentFlags ?? []) + (game.tideArchive?.persistentFlags ?? []) + Game.ownFlags)
        let graphOnly: Set<String> = ["returned", "route_begun", "gate_pages", "contradiction"]
        let strange = g.puzzles.flatMap { n in (n.requires + (n.sets.map { [$0] } ?? [])).filter { !gameFlags.contains($0) && !graphOnly.contains($0) }.map { "\(n.id): \($0)" } }
        check(strange.isEmpty, "puzzlegraph: every flag a puzzle needs or sets is a flag the game keeps, or one of the graph's own markers (\(strange))")
        check(g.external.subtracting(gameFlags).subtracting(graphOnly).isEmpty, "puzzlegraph: the flags walking grants are real (quay_seen) or the graph's own (gate_pages)")
        func answer(_ id: String) -> [String] { g.node(id)?.answer ?? [] }
        check(answer("stones") == LighthousePuzzle.order.map(\.name), "puzzlegraph: the stones' answer is LighthousePuzzle.order")
        check(answer("door-plates") == TonePlatePuzzle.order.map { StoneID(rawValue: $0)!.name }, "puzzlegraph: the plates' answer is TonePlatePuzzle.order")
        check(answer("mirror-court") == MirrorCourt.solutionPanes.map { StoneID(rawValue: $0)!.name }, "puzzlegraph: the mirror court's answer is its pane order")
        check(answer("chime-pool") == GlassWoodLogic.chimeSolution.map { StoneID(rawValue: [0, 2, 4].firstIndex(of: $0)!)!.name }, "puzzlegraph: the chimes' answer is the chime indices read as the stones' tones")
        check(answer("archive-gates-tone") == StoneID.allCases.map(\.name) && answer("archive-gates-beam") == answer("archive-gates-tone"), "puzzlegraph: the gates open tide, wind, stone, by either way")

        // Manipulation counts are computed; check them by an independent calculation.
        let search = PuzzleGraph.mirrorSearch()
        let byHand = zip(MirrorCourt.solutionMirrors, MirrorCourt.initialMirrors).map { ($0 - $1 + 4) % 4 }.reduce(0, +) + zip(MirrorCourt.solutionPanes, MirrorCourt.initialPanes).map { ($0 - $1 + 3) % 3 }.reduce(0, +)
        check(search.solutions == 1 && search.cheapest == byHand && g.node("mirror-court")?.manipulations == byHand, "puzzlegraph: the mirror court has exactly 1 of 1728 settings and the fewest clicks from where it is found is \(byHand) (search: \(search))")
        check(g.node("lens-ring")?.manipulations == 3, "puzzlegraph: the lens ring is 3 clicks from where it starts to the receiver")
        check(g.node("archive-gates-beam")?.manipulations == 15, "puzzlegraph: the prism ring is 15 clicks through the three marks in order (6 + 4 + 5)")
        check(g.node("stones")?.manipulations == 3 && g.node("door-plates")?.manipulations == 3 && g.node("chime-pool")?.manipulations == 3 && g.node("archive-gates-tone")?.manipulations == 3, "puzzlegraph: three strikes or touches each for the stones, plates, chimes and held-tone gates")

        // What the text says, and where the structure sits.
        check(g.pages.filter(\.statesOrder).map(\.id) == [3, 5, 6, 13], "puzzlegraph: the pages that state the order in words are 3, 5, 6 and 13 (\(g.pages.filter(\.statesOrder).map(\.id)))")
        check(g.pages.count == 15 && g.pages.allSatisfy { $0.position != nil }, "puzzlegraph: every one of the fifteen pages has a place in the world (an interactable box)")
        let today = R.timeline(g)
        check(today.map(\.id) == ["stones", "mirror-court", "chime-pool", "door-plates", "archive-gates-tone"] && today.map { $0.open.count } == [1, 2, 1, 1, 1], "puzzlegraph: today a player is offered 1, 2, 1, 1, 1 puzzles (\(today.map { $0.open.count }))")
        check(R.acyclic(g).isEmpty && R.flagsProvided(g).isEmpty && R.clueConsumers(g).isEmpty, "puzzlegraph: today's graph has no cycle, no unset flag and no clue without a consumer")
    }
}
